<script>
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');let W,H,DPR;function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const surnames=['RYO','NOVA','KAISER','VIPER','JIN','AKIRA','BRUMA','ZARA','TITAN','NEON','ONYX','KIRA','RAZE','SOLO','EMBER','LYNX','KNOX','SAGE','VOLT','ECHO','MORO','JUNO','FROST','HEX','DANTE','MIRA','ZERO','ORION','LUX','KODA','STORM','VEX','ARIA','DRAKE','BLAZE','NYX','RUNE','CYAN','ROOK','NIKO','CYRA','AXEL','WRAITH','FLUX','IRIS','TALON','GHOST','HADES','TERRA','SOL','QUINN','ATLAS','NOVA 2','EON'];
