function select(i){chosen=i;document.querySelectorAll('.portrait').forEach((e,j)=>e.classList.toggle('selected',j===i));let p=roster[i];document.getElementById('selname').textContent=p.name;document.getElementById('seldesc').textContent=p.style+' • PODER '+(70+i%30);document.getElementById('tags').innerHTML='<span>'+p.style+'</span><span>'+(['VELOCIDADE','FORÇA','TÉCNICA','DEFESA'][i%4])+'</span>'}
select(0);
function Fighter(x,p,dir){return{x,y:0,hp:100,vx:0,vy:0,dir,p,att:0,hit:0,flash:0,block:false}}let p1,p2;
function start(){let cpu=(chosen+17)%roster.length;p1=Fighter(W*.28,roster[chosen],1);p2=Fighter(W*.72,roster[cpu],-1);document.getElementById('p1name').textContent=p1.p.name;document.getElementById('p1style').textContent=p1.p.style;document.getElementById('p2name').textContent=p2.p.name;document.getElementById('p2style').textContent=p2.p.style;document.getElementById('select').style.display='none';game=true;timeLeft=60;timerAcc=0;let r=document.getElementById('round');r.textContent='ROUND 1';r.style.opacity=1;setTimeout(()=>r.style.opacity=0,1100)}document.getElementById('begin').onclick=start;
addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault()});addEventListener('keyup',e=>keys[e.code]=false);
document.querySelectorAll('[data-key]').forEach(b=>{let code=b.dataset.key;b.addEventListener('pointerdown',e=>{e.prevent;keys[code]=true;b.setPointerCapture(e.pointerId)});b.addEventListener('pointerup',()=>keys[code]=false);b.addEventListener('pointercancel',()=>keys[code]=false)});
function hit(a,b,power){let d=Math.abs(a.x-b.x);if(d<155&&b.hit<=0){b.hp=Math.max(0,b.hp-power);b.hit=.25;b.vx=a.dir*(power*3);b.flash=.12;if(b.hp<=0)roundOver(a.p.name)}}
function roundOver(winner){game=false;let r=document.getElementById('round');r.textContent=winner+' VENCEU';r.style.opacity=1;setTimeout(()=>{r.style.opacity=0;document.getElementById('select').style.display='flex'},2200)}
function update(dt){if(!game)return;timerAcc+=dt;if(timerAcc>1){timerAcc-=1;timeLeft--;document.getElementById('timer').textContent=timeLeft;if(timeLeft<=0){game=false;let r=document.getElementById('round');r.textContent=(p1.hp>=p2.hp?p1.p.name:p2.p.name)+' VENCEU';r.style.opacity=1;setTimeout(()=>{r.style.opacity=0;document.getElementById('select').style.display='flex'},2200)}}
 let move=(keys.ArrowLeft?-1:0)+(keys.ArrowRight?1:0);p1.vx+=move*1400*dt;p1.block=keys.ArrowDown;if(keys.ArrowUp&&p1.y===0)p1.vy=-620; if(keys.KeyJ&&p1.att<=0){p1.att=.38;hit(p1,p2,7)} if(keys.KeyK&&p1.att<=0){p1.att=.55;hit(p1,p2,11)}
 // CPU
 let dist=p2.x-p1.x;if(Math.abs(dist)>130)p2.vx+=(dist>0?1:-1)*700*dt;else if(Math.random()<.025)p2.att=.45,hit(p2,p1,8);if(Math.abs(dist)<100&&Math.random()<.01)p2.block=true;else p2.block=false;
 [p1,p2].forEach(f=>{f.vx*=Math.pow(.08,dt);f.x+=f.vx*dt;f.y+=f.vy*dt;if(f.y<0)f.vy+=1500*dt;else{f.y=0;f.vy=0}f.att=Math.max(0,f.att-dt);f.hit=Math.max(0,f.hit-dt);f.flash=Math.max(0,f.flash-dt);f.x=Math.max(W*.12,Math.min(W*.88,f.x));f.dir=f===p1?(p2.x>p1.x?1:-1):(p1.x>p2.x?1:-1)});document.getElementById('p1hp').style.width=p1.hp+'%';document.getElementById('p2hp').style.width=p2.hp+'%'}
