function fighter(f){let ground=H*.73-f.y*(.15);let scale=.78+ground/H*.55,dir=f.dir;ctx.save();ctx.translate(f.x,ground);ctx.scale(dir*scale,scale);ctx.globalAlpha=f.flash?.65:1;ctx.fillStyle='rgba(0,0,0,.45)';ctx.beginPath();ctx.ellipse(0,8,55,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#111827';ctx.fillRect(-28,0,23,105);ctx.fillRect(7,0,23,105);ctx.fillStyle=f.p.color;ctx.beginPath();ctx.moveTo(-38,105);ctx.lineTo(-12,105);ctx.lineTo(-14,130);ctx.lineTo(-48,130);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(12,105);ctx.lineTo(38,105);ctx.lineTo(48,130);ctx.lineTo(14,130);ctx.closePath();ctx.fill();ctx.fillStyle=f.p.color;ctx.beginPath();ctx.moveTo(-30,-20);ctx.quadraticCurveTo(0,-45,30,-20);ctx.lineTo(38,82);ctx.quadraticCurveTo(0,105,-38,82);ctx.closePath();ctx.fill();ctx.fillStyle='#151a29';ctx.fillRect(-12,-5,24,76);let swing=f.att>0?-55+(f.att/.55)*45:0;ctx.fillStyle=f.p.skin;ctx.save();ctx.translate(-30,5);ctx.rotate(-.65+swing*.018);ctx.fillRect(-10,-5,18,78);ctx.restore();ctx.save();ctx.translate(30,5);ctx.rotate(.65-swing*.018);ctx.fillRect(-8,-5,18,78);ctx.restore();ctx.fillStyle=f.p.skin;ctx.beginPath();ctx.arc(0,-48,31,0,Math.PI*2);ctx.fill();ctx.fillStyle=f.p.hair;ctx.beginPath();ctx.arc(-2,-57,32,Math.PI,Math.PI*2);ctx.lineTo(29,-43);ctx.lineTo(-25,-43);ctx.fill();ctx.fillStyle='#10131d';ctx.fillRect(-14,-50,9,4);ctx.fillRect(8,-50,9,4);ctx.fillStyle='#fff';ctx.fillRect(-11,-49,3,2);ctx.fillRect(11,-49,3,2);if(f.att>0){ctx.fillStyle='#fff';ctx.globalAlpha=.7;ctx.beginPath();ctx.arc(dir>0?70:-70,35,18,0,Math.PI*2);ctx.fill()}ctx.restore();}
function loop(now){let dt=Math.min(.033,(now-last)/1000);last=now;update(dt);drawArena();if(p1&&p2){fighter(p1);fighter(p2)}requestAnimationFrame(loop)}requestAnimationFrame(loop);
</script></body></html>
